import { useCallback, useEffect, useRef, useState } from 'react';
import toast from 'react-hot-toast';
import { generateReference } from '../lib/utils';

declare global {
  interface Window {
    PaystackPop: {
      setup: (config: {
        key: string;
        email: string;
        amount: number;
        currency: string;
        ref: string;
        subaccount?: string;
        transaction_charge?: number;
        bearer?: string;
        metadata?: Record<string, unknown>;
        callback: (response: { reference: string }) => void;
        onClose: () => void;
      }) => { openIframe: () => void };
    };
  }
}

type Props = {
  email?: string;
  amount: number;
  billId: string;
  venueId: string;
  onSuccess: (reference: string) => void;
  onClose?: () => void;
  children?: React.ReactNode;
  disabled?: boolean;
  className?: string;
};

export function PaystackButton({
  email,
  amount,
  billId,
  venueId,
  onSuccess,
  onClose,
  children,
  disabled,
  className,
}: Props) {
  const [scriptReady, setScriptReady] = useState(() => {
    return typeof window.PaystackPop !== 'undefined';
  });

  useEffect(() => {
    if (typeof window.PaystackPop !== 'undefined') {
      setScriptReady(true);
      return;
    }
    if (document.querySelector('script[src*="paystack"]')) {
      return; // will flip flag onload below
    }
    const script = document.createElement('script');
    script.src = 'https://js.paystack.co/v1/inline.js';
    script.async = true;
    script.onload = () => setScriptReady(true);
    document.body.appendChild(script);
  }, []);

  const handlePayment = useCallback(() => {
    const key = import.meta.env.PROD
      ? import.meta.env.VITE_PAYSTACK_LIVE_KEY || ''
      : import.meta.env.VITE_PAYSTACK_PUBLIC_KEY || '';
    if (!key || key.startsWith('pk_test_placeholder') || key.startsWith('pk_live_placeholder')) {
      toast.error("Payments aren't set up yet — the venue is missing its Paystack key.");
      return;
    }
    if (amount <= 0) {
      toast.error("Nothing due — this bill is already settled.");
      return;
    }
    if (!window.PaystackPop) {
      toast.error("Payment is still loading — please try again in a second.");
      return;
    }

    const ref = generateReference();
    const amountPesewas = Math.round(amount * 100);

    const config: Parameters<typeof window.PaystackPop.setup>[0] = {
      key,
      email: email || `${billId.slice(0, 8)}@bysen.com`,
      amount: amountPesewas,
      currency: 'GHS',
      ref,
      metadata: {
        bill_id: billId,
        venue_id: venueId,
        custom_fields: [{ variable_name: 'bill_id', value: billId }],
      },
      callback: (response) => {
        onSuccess(response.reference);
      },
      onClose: () => {
        onClose?.();
      },
    };

    const handler = window.PaystackPop.setup(config);
    handler.openIframe();
  }, [amount, billId, venueId, email, onSuccess, onClose]);

  return (
    <button
      type="button"
      onClick={handlePayment}
      disabled={disabled || !scriptReady}
      className={className}
    >
      {children}
    </button>
  );
}

import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from "react";

/* ═══════════════════════════════════════════════════════════════════════════
   Brand Color System — replaces hardcoded colors with CSS custom properties
   Default: Black (#000000) & White (#FFFFFF) 
   ═══════════════════════════════════════════════════════════════════════════ */

export type BrandColors = {
    primary: string;       // Main brand (licorice)
    secondary: string;     // Surface/bg (isabelline)
    accent: string;        // Accent (khaki)
    textSecondary: string; // Secondary text (feldgrau)
    danger: string;        // Danger/error (dark-red)
    lightBlue: string;     // Light blue accent
};

const DEFAULT_BRAND: BrandColors = {
    primary: "#23140C",
    secondary: "#F3F3E3",
    accent: "#D0BA98",
    textSecondary: "#606F69",
    danger: "#91040C",
    lightBlue: "#A9CFE0",
};

type BrandContextValue = {
    brand: BrandColors;
    setBrand: (colors: Partial<BrandColors>) => void;
    resetBrand: () => void;
    isDefault: boolean;
};

const STORAGE_KEY = "nightos-brand-colors-v2";

function loadBrand(): BrandColors {
    try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
            const parsed = JSON.parse(saved);
            return { ...DEFAULT_BRAND, ...parsed };
        }
    } catch {}
    return { ...DEFAULT_BRAND };
}

function applyBrandVars(brand: BrandColors) {
    const root = document.documentElement;
    root.style.setProperty("--brand-primary", brand.primary);
    root.style.setProperty("--brand-secondary", brand.secondary);
    root.style.setProperty("--brand-accent", brand.accent);
    root.style.setProperty("--brand-text-secondary", brand.textSecondary);
    root.style.setProperty("--brand-danger", brand.danger);
    root.style.setProperty("--brand-light-blue", brand.lightBlue);

    /* ── Derived / computed tints ── */
    root.style.setProperty("--brand-primary-rgb", hexToRgb(brand.primary));
    root.style.setProperty("--brand-secondary-rgb", hexToRgb(brand.secondary));
    root.style.setProperty("--brand-accent-rgb", hexToRgb(brand.accent));
    root.style.setProperty("--brand-danger-rgb", hexToRgb(brand.danger));
}

function hexToRgb(hex: string): string {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    if (!result) return "0,0,0";
    return `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`;
}

function colorsEqual(a: BrandColors, b: BrandColors): boolean {
    return (
        a.primary === b.primary &&
        a.secondary === b.secondary &&
        a.accent === b.accent &&
        a.textSecondary === b.textSecondary &&
        a.danger === b.danger &&
        a.lightBlue === b.lightBlue
    );
}

const BrandContext = createContext<BrandContextValue | null>(null);

export function BrandProvider({ children }: { children: ReactNode }) {
    const [brand, setBrandState] = useState<BrandColors>(loadBrand);

    // Apply on mount & when brand changes
    useEffect(() => {
        applyBrandVars(brand);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(brand));
    }, [brand]);

    const setBrand = useCallback((partial: Partial<BrandColors>) => {
        setBrandState((prev) => ({ ...prev, ...partial }));
    }, []);

    const resetBrand = useCallback(() => {
        setBrandState({ ...DEFAULT_BRAND });
    }, []);

    const isDefault = colorsEqual(brand, DEFAULT_BRAND);

    return (
        <BrandContext.Provider value={{ brand, setBrand, resetBrand, isDefault }}>
            {children}
        </BrandContext.Provider>
    );
}

export function useBrand() {
    const ctx = useContext(BrandContext);
    if (!ctx) throw new Error("useBrand must be used within a BrandProvider");
    return ctx;
}

import { createContext, useContext, useEffect, useRef, useState } from 'react'
import { useNetworkStatus } from '../hooks/useNetworkStatus'

type NetworkContextValue = {
  isOnline: boolean
  isNetworkTimeout: boolean
  triggerGlobalSync: () => Promise<unknown>
  resolveGlobalSync: (success: boolean) => void
  clearNetworkTimeout: () => void
  syncCount: number
}

const NetworkContext = createContext<NetworkContextValue>(null!)

let globalLastAutoSync = 0
const AUTO_SYNC_THROTTLE_MS = 5 * 60 * 1000

export function NetworkProvider({ children }: { children: React.ReactNode }) {
  const { status } = useNetworkStatus()
  const [isOnline, setIsOnline] = useState(status === 'online')
  const [isNetworkTimeout, setIsNetworkTimeout] = useState(false)
  const [syncCount, setSyncCount] = useState(0)

  const syncResolverRef = useRef<((value: unknown) => void) | null>(null)

  useEffect(() => { setIsOnline(status === 'online') }, [status])

  useEffect(() => {
    const tryAutoSync = () => {
      if (status !== 'online') return
      const now = Date.now()
      if (now - globalLastAutoSync < AUTO_SYNC_THROTTLE_MS) return
      globalLastAutoSync = now
      setSyncCount((c) => c + 1)
    }
    const handleFocus = () => tryAutoSync()
    const handleVisibility = () => {
      if (document.visibilityState === 'visible') tryAutoSync()
    }
    window.addEventListener('focus', handleFocus)
    document.addEventListener('visibilitychange', handleVisibility)
    return () => {
      window.removeEventListener('focus', handleFocus)
      document.removeEventListener('visibilitychange', handleVisibility)
    }
  }, [status])

  const triggerGlobalSync = () => new Promise((resolve) => { syncResolverRef.current = resolve; setSyncCount((c) => c + 1) })

  const resolveGlobalSync = (success: boolean) => {
    syncResolverRef.current?.(success)
    syncResolverRef.current = null
  }

  const clearNetworkTimeout = () => setIsNetworkTimeout(false)

  return (
    <NetworkContext.Provider value={{ isOnline, isNetworkTimeout, triggerGlobalSync, resolveGlobalSync, clearNetworkTimeout, syncCount }}>
      {children}
    </NetworkContext.Provider>
  )
}

export function useNetwork() {
  const ctx = useContext(NetworkContext)
  if (!ctx) throw new Error('useNetwork must be used inside <NetworkProvider>')
  return ctx
}

import { useCallback, useEffect, useState } from 'react'
import { supabase } from '../lib/supabase'
import { db, type DbBill } from '../lib/api'

export type CustomerSession = {
  id: string
  venue_id: string
  table_id: string
  bill_id: string | null
  guest_name: string
  party_size: number
  session_token: string
  status: 'active' | 'closed' | 'expired'
  created_at: string
  last_active_at: string
}

export type AssignedWaiter = {
  id: string
  name: string
}

type SessionState = {
  session: CustomerSession | null
  bill: DbBill | null
  waiter: AssignedWaiter | null
  loading: boolean
  error: string | null
}

export function useCustomerSession(venueId: string | null, tableId: string | null) {
  const [state, setState] = useState<SessionState>({
    session: null,
    bill: null,
    waiter: null,
    loading: false,
    error: null,
  })

  const assignWaiter = useCallback(async (billId: string, token: string) => {
    const { data: waiterId } = await supabase
      .rpc('assign_waiter_to_bill', { p_bill_id: billId })
      .setHeader('x-session-token', token)
    if (!waiterId) {
      setState((s) => ({ ...s, waiter: null }))
      return
    }
    const { data: staff } = await supabase
      .from('staff')
      .select('id, name')
      .eq('id', waiterId as string)
      .maybeSingle()
    setState((s) => ({ ...s, waiter: staff ? { id: staff.id, name: staff.name } : null }))
  }, [])

  const ensureSession = useCallback(async () => {
    if (!venueId || !tableId) return

    setState((s) => ({ ...s, loading: true, error: null }))

    // 1. Try to find existing active session for this table
    const { data: existingSession, error: sessionErr } = await supabase
      .from('customer_sessions')
      .select('*')
      .eq('venue_id', venueId)
      .eq('table_id', tableId)
      .eq('status', 'active')
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle()

    if (sessionErr) {
      setState((s) => ({ ...s, session: null, bill: null, loading: false, error: 'Failed to load session' }))
      return
    }

    let session = existingSession as CustomerSession | null

    // 1b. Session expired (20 min, never ordered) → block ordering until the
    // customer re-scans the table QR code. The waiter/manager keeps seeing
    // the expired session as "landed, never ordered".
    if (!session) {
      const { data: latestSession } = await supabase
        .from('customer_sessions')
        .select('*')
        .eq('venue_id', venueId)
        .eq('table_id', tableId)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle()

      if (latestSession && latestSession.status === 'expired') {
        setState((s) => ({ ...s, session: latestSession as CustomerSession, bill: null, loading: false, error: null }))
        return
      }
    }

    let bill = null

    // 2. If no active session, create one
    if (!session) {
      const { data: newSession, error: createErr } = await supabase
        .from('customer_sessions')
        .insert({
          venue_id: venueId,
          table_id: tableId,
          guest_name: 'Guest',
          party_size: 1,
        })
        .select()
        .single()

      if (createErr || !newSession) {
        setState((s) => ({ ...s, session: null, bill: null, loading: false, error: 'Failed to create session' }))
        return
      }
      session = newSession as CustomerSession
    }

    const token = session.session_token

    // 3. The session's own bill always wins (it may differ from the newest
    // open bill if a stale duplicate was left on the table). Fall back to
    // the newest open bill only when the session has none.
    if (session.bill_id) {
      const { data: sessionBill, error: sessionBillErr } = await db.billById(session.bill_id)
      if (sessionBillErr) {
        setState((s) => ({ ...s, session, bill: null, loading: false, error: 'Failed to load bill' }))
        return
      }
      if (sessionBill && (sessionBill.status === 'open' || sessionBill.status === 'settling')) {
        bill = sessionBill
      }
    }

    if (!bill) {
      // 3b. Open or create bill for this table
      const { data: existingBill, error: billErr } = await db.openBillForTable(tableId)
      if (billErr) {
        setState((s) => ({ ...s, session, bill: null, loading: false, error: 'Failed to load bill' }))
        return
      }

      if (existingBill) {
        bill = existingBill
        if (session.bill_id !== existingBill.id) {
          await supabase
            .from('customer_sessions')
            .update({ bill_id: existingBill.id })
            .setHeader('x-session-token', token)
            .eq('id', session.id)
          session = { ...session, bill_id: existingBill.id }
        }
      } else {
        const { data: newBill, error: createBillErr } = await db.createBill(
          venueId,
          tableId,
          session.party_size || 1,
          token,
        )
        if (createBillErr || !newBill) {
          setState((s) => ({ ...s, session, bill: null, loading: false, error: 'Failed to create bill' }))
          return
        }
        bill = newBill
        await supabase
          .from('customer_sessions')
          .update({ bill_id: newBill.id })
          .setHeader('x-session-token', token)
          .eq('id', session.id)
        session = { ...session, bill_id: newBill.id }
      }
    }

    setState((s) => ({ ...s, session, bill, loading: false, error: null }))

    // 4. Make sure the bill has a waiter (idempotent, people-weighted)
    if (bill) assignWaiter(bill.id, token)
  }, [venueId, tableId, assignWaiter])

  useEffect(() => {
    ensureSession()
  }, [ensureSession])

  /**
   * Customer confirms their party size before ordering. Updates the
   * session + bill (guest_count feeds waiter load balancing) and then
   * (re)assigns the waiter with the new headcount.
   */
  const updateParty = useCallback(
    async (partySize: number, guestName?: string) => {
      const { session, bill } = state
      if (!session || !bill) return { error: 'Session not ready' }

      const name = guestName?.trim() || session.guest_name || 'Guest'
      const { data: updated, error } = await supabase
        .from('customer_sessions')
        .update({ party_size: partySize, guest_name: name })
        .setHeader('x-session-token', session.session_token)
        .eq('id', session.id)
        .select()
        .single()

      if (error) return { error: 'Failed to save party size' }

      const { error: billErr } = await db.updateBill(bill.id, { guest_count: partySize }, session.session_token)
      if (billErr) return { error: 'Failed to save party size' }

      setState((s) => ({
        ...s,
        session: { ...(updated as CustomerSession), bill_id: s.session?.bill_id ?? null },
        bill: bill ? { ...bill, guest_count: partySize } : bill,
      }))

      await assignWaiter(bill.id, session.session_token)
      return { error: null }
    },
    [state, assignWaiter],
  )

  const refresh = useCallback(() => {
    ensureSession()
  }, [ensureSession])

  return { ...state, refresh, updateParty }
}

import { useState, useCallback, useRef, useEffect } from 'react'

export function useMutation<TData = unknown, TError = unknown, TArgs extends unknown[] = unknown[]>(
  mutator: (...args: TArgs) => Promise<{ data: TData | null; error: TError | null }>,
  options?: { onSuccess?: (data: TData) => void; onError?: (err: TError) => void },
) {
  const INITIAL = { data: null as TData | null, error: null as TError | null, loading: false }
  const [state, setState] = useState(INITIAL)
  const mutatorRef = useRef(mutator)
  const onSuccessRef = useRef(options?.onSuccess)
  const onErrorRef = useRef(options?.onError)

  useEffect(() => {
    mutatorRef.current = mutator
    onSuccessRef.current = options?.onSuccess
    onErrorRef.current = options?.onError
  })

  const mutate = useCallback(async (...args: TArgs) => {
    setState({ data: null, error: null, loading: true })
    try {
      const { data, error } = await mutatorRef.current(...args)
      if (error) throw error
      setState({ data, error: null, loading: false })
      onSuccessRef.current?.(data)
      return { data, error: null }
    } catch (err) {
      setState({ data: null, error: err, loading: false })
      onErrorRef.current?.(err)
      return { data: null, error: err }
    }
  }, [])

  const reset = useCallback(() => setState(INITIAL), [])

  return { ...state, mutate, reset }
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { supabase } from '../lib/supabase';
import { db, type DbOrderSubmission } from '../lib/api';

type OrdersState = {
  orders: DbOrderSubmission[];
  loading: boolean;
  error: string | null;
};

export function useOrders(venueId: string | null, station?: string) {
  const [state, setState] = useState<OrdersState>({ orders: [], loading: true, error: null });

  const fetchOrders = useCallback(async () => {
    if (!venueId) {
      setState({ orders: [], loading: false, error: null });
      return;
    }
    setState((s) => ({ ...s, loading: true }));
    const { data, error } = await db.orderSubmissionsByVenue(venueId, station);
    if (error) {
      setState({ orders: [], loading: false, error: 'Failed to fetch orders' });
      return;
    }
    setState({ orders: data ?? [], loading: false, error: null });
  }, [venueId, station]);

  useEffect(() => {
    const init = async () => {
        await fetchOrders();
    };
    init();
    }, [fetchOrders]);

  const onInsertRef = useRef<((row: DbOrderSubmission) => void) | null>(null);
  const onUpdateRef = useRef<((row: DbOrderSubmission) => void) | null>(null);

  useEffect(() => {
    onInsertRef.current = (row: DbOrderSubmission) => {
      setState((s) => ({ ...s, orders: [row, ...s.orders] }));
    };
    onUpdateRef.current = (row: DbOrderSubmission) => {
      setState((s) => ({
        ...s,
        orders: s.orders.map((o) => (o.id === row.id ? row : o)),
      }));
    };
  }, []);

  useEffect(() => {
    if (!venueId) return;

    const filter = `venue_id=eq.${venueId}`;
    const channel = supabase
      .channel(`orders:${venueId}-${Math.random().toString(36).slice(2, 9)}`)
      .on(
        'postgres_changes' as never,
        {
          event: '*',
          schema: 'public',
          table: 'order_submissions',
          filter,
        },
        (payload: any) => {
          if (payload.eventType === 'INSERT') onInsertRef.current?.(payload.new);
          else if (payload.eventType === 'UPDATE') onUpdateRef.current?.(payload.new);
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [venueId]);

  return { ...state, refresh: fetchOrders };
}

import { useEffect, useState } from 'react'
import { db, type DbTable } from '../lib/api'

type QrState = {
  table: DbTable | null
  loading: boolean
  error: boolean
}

export function useQrTable(token: string | null) {
  const [state, setState] = useState<QrState>({ table: null, loading: false, error: false })

  useEffect(() => {
    if (!token) {
      setState({ table: null, loading: false, error: false })
      return
    }

    let cancelled = false

    async function resolve() {
      setState({ table: null, loading: true, error: false })
      const { data, error } = await db.tableByQrToken(token ?? '')
      if (cancelled) return
      if (error || !data) {
        setState({ table: null, loading: false, error: true })
        return
      }
      setState({ table: data, loading: false, error: false })
    }

    resolve()
    return () => {
      cancelled = true
    }
  }, [token])

  return state
}

