        <ChevronDownIcon className="ml-2 h-4 w-4 -rotate-90 text-feldgrau/50" strokeWidth={2.25} />
      </button>
      {open && (
        <ReceiptModal
          order={order}
          venueName={venueName}
          sessionToken={sessionToken}
          onClose={() => setOpen(false)}
