                                            <span className="inline-flex items-center gap-1 rounded-full bg-isabelline px-4 py-2 text-[11px] font-bold tracking-tight text-feldgrau">
                                                Tickets at the venue
                                            </span>
                                        </div>
                                    </div>
                                </article>
                            ))}
                        </div>
                    </div>
