                            </p>
                            <h1 className="mt-1.5 text-[1.75rem] font-black leading-[1.05] tracking-[-0.04em] text-licorice">
                                Reserve your
                                <br />
                                <span className="italic font-serif font-bold text-khaki">
                                    corner of the lounge
                                </span>
                            </h1>
