function formatDateLong(iso: string): string {
    const d = new Date(`${iso}T00:00:00`);
    return d.toLocaleDateString("en-GH", { weekday: "short", day: "numeric", month: "short" });
}

function formatTimeShort(time: string): string {
    const [h, m] = time.slice(0, 5).split(":").map(Number);
    const ampm = h < 12 ? "AM" : "PM";
    const hr = h % 12 === 0 ? 12 : h % 12;
    return `${hr}:${String(m).padStart(2, "0")} ${ampm}`;
}

import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import toast from 'react-hot-toast'
import { useAuth } from '../../context/AuthContext'
import { normalizeGhanaPhone } from '../../lib/utils'

const OTP_STORAGE_KEY = 'nightos:otp_pending'
const OTP_COOLDOWN_SECONDS = 60

type Props = {
  isLogin: boolean
  onSwitchMethod: () => void
  onToggleMode: () => void
}

export function PhoneAuthForm({ isLogin, onSwitchMethod, onToggleMode }: Props) {
  const [phone, setPhone] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const { signInWithPhone } = useAuth()
  const navigate = useNavigate()

  const [cooldown, setCooldown] = useState(() => {
    try {
      const raw = sessionStorage.getItem(OTP_STORAGE_KEY)
      if (raw) {
        const { sentAt } = JSON.parse(raw)
        const elapsed = Math.floor((Date.now() - (sentAt || 0)) / 1000)
        const remaining = OTP_COOLDOWN_SECONDS - elapsed
        return remaining > 0 ? remaining : 0
      }
    } catch {}
    return 0
  })

  useEffect(() => {
    if (cooldown <= 0) return
    const t = setTimeout(() => setCooldown((c) => c - 1), 1000)
    return () => clearTimeout(t)
  }, [cooldown])

  // +233 normalization only for now — international formats come later.
  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault()
    if (cooldown > 0) return
    setError(null)
    setLoading(true)

    const formattedPhone = normalizeGhanaPhone(phone)
    if (!formattedPhone) {
      setError('Enter a valid Ghana phone number, e.g. 024 123 4567 or +233 24 123 4567.')
      setLoading(false)
      return
    }

    // No existence gate: OTP sends either way, and Supabase creates the
    // account on first successful verify. Sign-in and sign-up are the
    // same path for phone numbers.
    const { error } = await signInWithPhone(formattedPhone)
    setLoading(false)
    if (error) {
      const raw = error.message
      const hasRealDetail = /mnotify|api key|sender|balance|recipient/i.test(raw)
      setError(
        hasRealDetail
          ? raw
          : /SMS|provider|hook|configure|settings/i.test(raw)
            ? "SMS isn't set up on this Supabase project yet. Use 'Continue with Email' for now, or configure the mnotify-sms hook and MNOTIFY_API_KEY in Supabase."
            : raw,
      )
      toast.error(error.message)
    } else {
      toast.success('Code sent! Check your phone.')
      sessionStorage.setItem(
        OTP_STORAGE_KEY,
        JSON.stringify({ phone: formattedPhone, mode: isLogin ? 'login' : 'signup', sentAt: Date.now() }),
      )
      navigate('/verify-otp', { replace: true })
    }
  }

  return (
    <div>
      <div className="mb-6 text-center">
        <h2 className="text-xl font-bold tracking-tight text-licorice">
          {isLogin ? 'Sign in' : 'Create your venue'}
        </h2>
        <p className="text-[12px] tracking-tight text-feldgrau mt-1">
          {isLogin ? 'Enter your phone number to continue.' : 'Join Bysen in 5 minutes.'}
        </p>
      </div>

      <form onSubmit={handleSendOtp} className="space-y-4">
        <div>
          <label className="text-[10px] font-bold uppercase tracking-[0.18em] text-feldgrau">Phone number</label>
          <div className="mt-1.5 flex items-center gap-2 rounded-xl bg-white px-3.5 py-3 shadow-sm ring-1 ring-licorice/8 focus-within:ring-2 focus-within:ring-licorice/20">
            <input
              type="tel"
              required
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="+233 24 123 4567"
              autoComplete="tel"
              className="flex-1 min-w-0 bg-transparent text-[13px] text-licorice placeholder:text-feldgrau/50 focus:outline-none"
            />
          </div>
        </div>

        {error && (
          <div className="rounded-md border border-red-100 bg-red-50 px-4 py-3 text-[12px] text-red-700">{error}</div>
        )}

        <button
          type="submit"
          disabled={loading || cooldown > 0}
          className="w-full rounded-full bg-licorice px-5 py-3.5 text-[13px] font-bold text-isabelline shadow-[0_12px_28px_rgba(35,20,12,0.20)] transition-all hover:bg-licorice/95 active:scale-[0.985] disabled:opacity-80"
        >
          {loading ? 'Sending code...' : cooldown > 0 ? `Resend in ${cooldown}s` : 'Continue with Phone'}
        </button>
      </form>

      <div className="mt-6 relative">
        <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-licorice/8" /></div>
        <div className="relative flex justify-center"><span className="bg-isabelline px-3 text-[10px] font-medium uppercase tracking-wider text-feldgrau">Or</span></div>
      </div>

      <div className="mt-6 text-center">
        <button onClick={onSwitchMethod} className="text-[12px] font-semibold text-feldgrau hover:text-licorice transition-colors">
          Continue with Email instead
        </button>
      </div>

      <div className="mt-6 text-center text-[12px] text-feldgrau">
        {isLogin ? "Don't have a venue yet? " : 'Already have a venue? '}
        <button onClick={onToggleMode} className="font-semibold text-licorice hover:underline">
          {isLogin ? "Create one — it's free" : 'Sign in'}
        </button>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../../context/AuthContext'
import { authDb } from '../../lib/db/auth'

export function VenueSetupScreen() {
  const navigate = useNavigate()
  const { user, venue, refreshVenue } = useAuth()

  const [step, setStep] = useState(0)
  const [name, setName] = useState('')
  const [slug, setSlug] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [slugChecking, setSlugChecking] = useState(false)
  const [slugTaken, setSlugTaken] = useState(false)
  const [createError, setCreateError] = useState<string | null>(null)

  useEffect(() => {
    if (venue) navigate('/manager', { replace: true })
  }, [venue, navigate])

  useEffect(() => {
    if (step !== 1 || slug) return
    const generated = name.toLowerCase().replace(/[^a-z0-9-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '')
    if (generated) setSlug(generated)
  }, [step, name, slug])

  useEffect(() => {
    if (!slug || slug.length < 3) { setSlugTaken(false); return }
    setSlugChecking(true)
    const timer = setTimeout(async () => {
      const { count, error } = await authDb.slugAvailable(slug)
      setSlugTaken(!error && (count ?? 0) > 0)
      setSlugChecking(false)
    }, 400)
    return () => clearTimeout(timer)
  }, [slug])

  const slugValid = slug.length >= 3 && /^[a-z0-9-]+$/.test(slug) && !slugTaken && !slugChecking
  const canAdvance = name.trim().length >= 2

  const handleCreate = async () => {
    if (!user) return
    setSubmitting(true)
    setCreateError(null)
    const { data, error } = await authDb.createVenue(user.id, name.trim(), slug)
    setSubmitting(false)
    if (error || !data) {
      const conflict = error?.code === '23505' || String(error?.message || '').includes('duplicate key')
      setCreateError(conflict
        ? 'That URL is already taken. Try a different one (e.g. add a number at the end).'
        : `Could not create venue: ${error?.message || 'Unknown error'}`)
      return
    }
    await refreshVenue()
    navigate('/manager', { replace: true })
  }

  return (
    <div className="relative min-h-svh w-full bg-isabelline font-sans text-licorice antialiased flex flex-col items-center justify-center px-6 py-12">
      <div className="w-full max-w-md">
        <div className="mb-8 text-center">
          <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-feldgrau">
            Onboarding · Step {step + 1} of 2
          </p>
          <h1 className="mt-2 text-xl font-bold tracking-tight text-licorice">
            {step === 0 ? "What's your venue called?" : 'Pick your URL'}
          </h1>
          <p className="text-[12px] text-feldgrau mt-1">
            {step === 0 ? 'Give your nightclub or bar a name.' : 'Choose a unique link for your venue.'}
          </p>
        </div>

        {step === 0 && (
          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-bold uppercase tracking-[0.18em] text-feldgrau">Venue Name</label>
              <div className="mt-1.5 flex items-center gap-2 rounded-xl bg-white px-3.5 py-3 shadow-sm ring-1 ring-licorice/8 focus-within:ring-2 focus-within:ring-licorice/20">
                <input type="text" value={name}
                  onChange={(e) => setName(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && canAdvance && setStep(1)}
                  placeholder="e.g. Velvet Lounge"
                  autoFocus
                  className="flex-1 min-w-0 bg-transparent text-[13px] text-licorice placeholder:text-feldgrau/50 focus:outline-none" />
              </div>
            </div>
            <button onClick={() => setStep(1)} disabled={!canAdvance}
              className="w-full rounded-full bg-licorice px-5 py-3.5 text-[13px] font-bold text-isabelline shadow-sm transition-all hover:bg-licorice/95 active:scale-[0.985] disabled:opacity-40">
              Continue
            </button>
          </div>
        )}

        {step === 1 && (
          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-bold uppercase tracking-[0.18em] text-feldgrau">Venue URL</label>
              <div className="mt-1.5">
                <div className="flex items-center gap-2 rounded-xl bg-white px-3.5 py-3 shadow-sm ring-1 ring-licorice/8 focus-within:ring-2 focus-within:ring-licorice/20">
                  <span className="text-[12px] text-feldgrau">bysen.app/</span>
                  <input type="text" value={slug}
                    onChange={(e) => setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ''))}
                    placeholder="velvet-lounge"
                    autoFocus
                    className="flex-1 min-w-0 bg-transparent text-[13px] text-licorice placeholder:text-feldgrau/50 focus:outline-none font-mono" />
                </div>
                {slug.length >= 3 && (
                  <div className="mt-1.5 flex items-center gap-1.5">
                    {slugChecking ? (
                      <span className="text-[11px] text-feldgrau">Checking...</span>
                    ) : slugTaken ? (
                      <span className="text-[11px] text-red-600">Taken</span>
                    ) : (
                      <span className="text-[11px] text-emerald-600">Available</span>
                    )}
                  </div>
                )}
              </div>
            </div>
            {createError && (
              <p className="text-[11px] text-red-600">{createError}</p>
            )}
            <div className="flex gap-2">
              <button onClick={() => setStep(0)}
                className="flex-1 rounded-full bg-white px-5 py-3.5 text-[13px] font-bold text-licorice ring-1 ring-licorice/8 hover:bg-isabelline transition-all">
                Back
              </button>
              <button onClick={handleCreate} disabled={!slugValid || submitting}
                className="flex-1 rounded-full bg-licorice px-5 py-3.5 text-[13px] font-bold text-isabelline shadow-sm transition-all hover:bg-licorice/95 active:scale-[0.985] disabled:opacity-40">
                {submitting ? 'Creating...' : 'Create Venue'}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

