            </div>

            {/* ═══════════════════════════════════════════════════════════
               SETTLEMENT & FLOOR WATCH — platform fees owed, customers who
               landed but never ordered, open bills per table
               ═══════════════════════════════════════════════════════════ */}
            <div className="flex flex-col gap-8 bg-white p-6 rounded-2xl shadow-sm border border-slate-100 w-full">
                {/* Header Block */}
                <div className="flex items-center justify-between">
                    <h2 className="text-lg font-bold text-slate-900 tracking-tight">Platform Fees</h2>
                </div>

                {/* Primary KPI Block */}
                <div className="flex flex-col gap-2">
                    <div className="flex items-center gap-2">
                        <span className="text-xs font-bold uppercase tracking-wider text-slate-500">Owed to Bysen</span>
                        {/* Tooltip trigger replaces the paragraph of text */}
                        <svg className="w-4 h-4 text-slate-400 cursor-help" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                        </svg>
                    </div>
                    <div className="text-4xl font-bold text-slate-900 tabular-nums tracking-tight">
                        {formatGHS(outstanding)}
                    </div>
                </div>

                {/* Cash Fee Ledger Table */}
                <div className="flex flex-col gap-4 mt-2">
                    <h3 className="text-xs font-bold uppercase tracking-wider text-slate-400 border-b border-slate-100 pb-2">
                        Cash Fee Ledger
                    </h3>

                    <div className="flex flex-col">
                        {recentFees.length === 0 ? (
                            <p className="text-sm text-slate-500">No cash fees yet.</p>
                        ) : (
                            recentFees.map((p, i) => (
                                <div key={p.payment_id} className="grid grid-cols-[16px_1fr_auto_auto] items-center gap-3 py-3 border-b border-slate-50 whitespace-nowrap">
                                    <span className="text-sm font-medium text-slate-900">{i + 1}</span>
                                    <span className="text-sm text-slate-500">
                                        {new Date(p.created_at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
                                    </span>
                                    <span className="text-sm text-slate-500 tabular-nums">{formatGHS(p.amount)}</span>
                                    <span className="text-sm font-semibold text-slate-900 tabular-nums text-right min-w-[3rem]">
                                        {formatGHS(p.platform_fee)}
                                    </span>
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {/* Open Bills */}
                <div className="flex flex-col gap-4 mt-2">
                    <h3 className="text-xs font-bold uppercase tracking-wider text-slate-400 border-b border-slate-100 pb-2">
                        Open Bills
                    </h3>
                    {billGroups.length === 0 ? (
                        <p className="text-sm text-slate-500">
                            No open bills right now.
                        </p>
                    ) : (
                        <div className="flex flex-col">
                            {billGroups.map((group) => {
                                const total = group.reduce((sum, b) => sum + Number(b.total), 0);
                                const label = group.map((b) => b.table_label ?? `Table ${b.table_number}`).join(" + ");
                                return (
                                    <div key={group[0].bill_id} className="grid grid-cols-2 items-center gap-4 py-3 border-b border-slate-50 last:border-0">
                                        <span className="text-sm font-medium text-slate-900">{label}</span>
                                        <span className="text-sm font-semibold tabular-nums text-slate-900 text-right">{formatGHS(total)}</span>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>


        </div>
    );
}

import { useState, type FormEvent, type ReactNode } from "react";
import {
    ArrowRightIcon,
    ArrowRightStartOnRectangleIcon,
    BanknotesIcon,
    Bars3Icon,
    ChartBarIcon,
    ClipboardDocumentCheckIcon,
    EyeIcon,
    LockClosedIcon,
    MapIcon,
    MegaphoneIcon,
    Squares2X2Icon,
    UserCircleIcon,
    UserIcon,
    UsersIcon,
    XMarkIcon,
} from "@heroicons/react/24/outline";
import { ShieldCheckIcon } from "@heroicons/react/24/solid";
import signoutBlackIcon from "../../assets/sign-out-black.svg";
import { ManagerSignOutModal } from "../../components/ManagerSignOutModal";

/* ────────────────────────── Admin Login Screen ────────────────────────── */

type LoginProps = {
    onSignIn: (managerName: string) => void;
};

export function AdminLoginScreen({ onSignIn }: LoginProps) {
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [showPassword, setShowPassword] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        setError(null);
        if (!email.trim() || !password.trim()) {
            setError("Please enter your email and password.");
            return;
        }
        setLoading(true);
        window.setTimeout(() => {
            setLoading(false);
            const name = email.split("@")[0].replace(/[^a-zA-Z]/g, "").replace(/^\w/, (c) => c.toUpperCase());
            onSignIn(name || "Manager");
        }, 1200);
    };

    return (
        <main className="relative min-h-svh w-full overflow-x-hidden bg-isabelline font-sans text-licorice antialiased flex flex-col">
            {/* Top brand bar */}
            <div className="px-6 pt-[max(env(safe-area-inset-top),24px)] pb-4">
                <div className="flex items-center gap-2.5">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-licorice text-isabelline shadow-[0_4px_14px_rgba(35,20,12,0.25)]">
                        <span className="font-serif text-[16px] font-bold leading-none tracking-tight">V</span>
                    </div>
                    <div className="flex flex-col leading-tight">
                        <span className="text-[14px] font-bold tracking-tight text-licorice">Velvet Lounge</span>
                        <span className="text-xs font-semibold uppercase text-feldgrau">Manager Portal · Bysen</span>
                    </div>
                </div>
            </div>

            {/* Main content */}
            <div className="flex flex-1 items-center justify-center px-6 py-8">
                <div className="w-full max-w-sm">
                    <div className="mb-8">
                        <p className="text-xs font-bold uppercase text-khaki">Admin Sign In</p>
                        <h1 className="mt-1.5 text-[2rem] font-black leading-[1.05] tracking-[-0.04em] text-licorice">
                            Control room
                            <br />
                            <span className="italic font-serif font-bold text-khaki">for the floor</span>
                        </h1>
                        <p className="mt-2 max-w-[320px] text-[12.5px] leading-[1.55] tracking-tight text-feldgrau">
                            Live ops, menus, staff, finance, and CRM — all in one dashboard.
                        </p>
                    </div>

                    <form onSubmit={handleSubmit} className="flex flex-col gap-3">
                        <div>
                            <label htmlFor="admin-email" className="text-xs font-bold uppercase text-feldgrau">Email</label>
                            <div className="mt-1.5 flex items-center gap-2 rounded-xl bg-white px-3.5 py-3 shadow-sm ring-1 ring-licorice/8 focus-within:ring-2 focus-within:ring-licorice/20 transition-all">
                                <UserIcon className="h-4 w-4 shrink-0 text-feldgrau" strokeWidth={2} />
                                <input
                                    id="admin-email"
                                    type="email"
                                    autoComplete="email"
                                    autoFocus
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    placeholder="manager@velvetlounge.gh"
                                    className="flex-1 min-w-0 bg-transparent text-[13px] text-licorice placeholder:text-feldgrau/50 focus:outline-none"
                                />
                            </div>
                        </div>

                        <div>
                            <label htmlFor="admin-password" className="text-xs font-bold uppercase text-feldgrau">Password</label>
                            <div className="mt-1.5 flex items-center gap-2 rounded-xl bg-white px-3.5 py-3 shadow-sm ring-1 ring-licorice/8 focus-within:ring-2 focus-within:ring-licorice/20 transition-all">
                                <LockClosedIcon className="h-4 w-4 shrink-0 text-feldgrau" strokeWidth={2} />
                                <input
                                    id="admin-password"
                                    type={showPassword ? "text" : "password"}
                                    autoComplete="current-password"
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                    placeholder="••••••••"
                                    className="flex-1 min-w-0 bg-transparent text-[13px] text-licorice placeholder:text-feldgrau/50 focus:outline-none"
                                />
                                <button
                                    type="button"
                                    onClick={() => setShowPassword((v) => !v)}
                                    aria-label={showPassword ? "Hide password" : "Show password"}
                                    className="text-feldgrau transition-colors hover:text-licorice"
                                >
                                    <EyeIcon className="h-4 w-4" strokeWidth={2} />
                                </button>
                            </div>
                        </div>

                        {error && (
                            <p className="rounded-lg bg-dark-red/8 px-3 py-2 text-xs font-semibold tracking-tight text-dark-red">{error}</p>
                        )}

                        <button
                            type="submit"
                            disabled={loading}
                            className="mt-2 flex items-center justify-center gap-2 rounded-full bg-licorice px-5 py-3.5 text-[13px] font-bold tracking-tight text-isabelline shadow-[0_12px_28px_rgba(35,20,12,0.20)] ring-1 ring-licorice/80 transition-all duration-200 hover:bg-licorice/95 active:scale-[0.985] disabled:opacity-80"
                        >
                            {loading ? (
                                <>
                                    <svg className="h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none">
                                        <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" strokeOpacity="0.25" />
                                        <path d="M22 12a10 10 0 0 1-10 10" stroke="currentColor" strokeWidth="3" strokeLinecap="round" />
                                    </svg>
                                    Signing in…
                                </>
                            ) : (
                                <>
                                    Sign In
                                    <ArrowRightIcon className="h-4 w-4" strokeWidth={2.5} />
                                </>
                            )}
                        </button>
                    </form>
                </div>
            </div>

            {/* Footer */}
            <div className="px-6 pb-[max(env(safe-area-inset-bottom),20px)] pt-4">
                <div className="flex items-center justify-center gap-1.5 text-xs font-semibold tracking-tight text-feldgrau">
                    <ShieldCheckIcon className="h-3.5 w-3.5" strokeWidth={2} />
                    <span>Secured by Bysen · Supabase Auth</span>
                </div>
            </div>
        </main>
    );
}

/* ────────────────────────── Manager Shell ────────────────────────── */

export type ManagerPage =
    | "ops"
    | "floorplan"
    | "menu"
    | "staff"
    | "finance"
    | "crm";

type NavItem = {
    id: ManagerPage;
    label: string;
    icon: typeof Squares2X2Icon;
};

const NAV_ITEMS: NavItem[] = [
    { id: "ops", label: "Live Ops", icon: Squares2X2Icon },
    { id: "floorplan", label: "Floorplan", icon: MapIcon },
    { id: "menu", label: "Menu & Inventory", icon: ClipboardDocumentCheckIcon },
    { id: "staff", label: "Staff & Roles", icon: UsersIcon },
    { id: "finance", label: "Financial Reports", icon: BanknotesIcon },
    { id: "crm", label: "CRM & Marketing", icon: MegaphoneIcon },
];

type ShellProps = {
    managerName: string;
    activePage: ManagerPage;
    onPageChange: (page: ManagerPage) => void;
    onSignOut: () => void;
    children: ReactNode;
};

