                                            />
                                        </div>
                                    </div>

                                    {error && (
                                        <div className="rounded-md border border-red-100 bg-red-50 px-4 py-3 text-sm text-red-700">
                                            {error}
                                        </div>
                                    )}

                                    <button
                                        type="submit"
                                        disabled={cooldown > 0 || loading}
